def transform(grid):
    """Expand each seed along its matching contiguous color sequence in the last row."""
    out = [row[:] for row in grid]
    # The sequence exemplars are contiguous nonzero runs on the top and
    # bottom edges; either edge can carry an exemplar.
    sequences = []
    for key in (grid[0], grid[-1]):
        run = []
        for value in key:
            if value:
                run.append(value)
            elif run:
                sequences.append(run)
                run = []
        if run:
            sequences.append(run)

    for r, row in enumerate(grid[1:-1], start=1):
        for c, value in enumerate(row):
            if not value:
                continue
            seq = next((s for s in sequences if value in s), None)
            if seq is None:
                continue
            anchor = seq.index(value)
            start = c - anchor
            for i, color in enumerate(seq):
                x = start + i
                if 0 <= x < len(row) and out[r][x] == 0:
                    out[r][x] = color
    return out
